pub struct NativeHeaderDatum { pub key: &'static str, pub values: &'static [&'static str] }
#[derive(Clone, Copy, Debug)]
pub struct NativeHeader { pub stamp: Option<NativeStamp>, pub data: &'static [NativeHeaderDatum], pub wire: &'static [u8] }
#[derive(Clone, Copy, Debug)]
pub struct NativeVector3 { pub header: Option<&'static NativeHeader>, pub xyz: [u64; 3], pub wire: &'static [u8] }
#[derive(Clone, Copy, Debug)]
pub struct NativeQuaternion { pub header: Option<&'static NativeHeader>, pub xyzw: [u64; 4], pub wire: &'static [u8] }
#[derive(Clone, Copy, Debug)]
pub struct NativePose { pub header: Option<&'static NativeHeader>, pub name: &'static str, pub id: u32, pub position: Option<&'static NativeVector3>, pub orientation: Option<&'static NativeQuaternion>, pub wire: &'static [u8] }
#[derive(Clone, Copy, Debug)]
pub struct NativeAxis { pub header: Option<&'static NativeHeader>, pub xyz: Option<&'static NativeVector3>, pub lower: u64, pub upper: u64, pub damping: u64, pub position: u64, pub velocity: u64, pub wire: &'static [u8] }
#[derive(Clone, Copy, Debug)]
pub struct NativeJointMessage { pub header: Option<&'static NativeHeader>, pub name: &'static str, pub id: u32, pub kind: i32, pub parent: &'static str, pub parent_id: u32, pub child: &'static str, pub child_id: u32, pub pose: Option<&'static NativePose>, pub axis1: Option<&'static NativeAxis>, pub axis2: Option<&'static NativeAxis>, pub wire: &'static [u8] }
#[derive(Clone, Copy, Debug)]
pub struct NativeModelMessage { pub header: Option<&'static NativeHeader>, pub name: &'static str, pub id: u32, pub is_static: bool, pub deleted: bool, pub self_collide: bool, pub pose: Option<&'static NativePose>, pub joints: &'static [NativeJointMessage], pub wire: &'static [u8] }
#[derive(Clone, Copy, Debug)]
pub struct NativeJointConfiguration { pub entity: u64, pub parent_entity: u64, pub name: &'static str, pub parent_link: &'static str, pub child_link: &'static str, pub local_pose: [u64; 7], pub axis: [u64; 3], pub lower: u64, pub upper: u64, pub damping: u64, pub selected: bool }
#[derive(Clone, Copy, Debug)]
pub struct NativeConfiguration { pub owner: usize, pub world_entity: u64, pub model_entity: u64, pub world_name: &'static str, pub model_name: &'static str, pub full_name: &'static str, pub requested_topic: &'static str, pub resolved_topic: &'static str, pub rate: u64, pub xml: &'static str, pub model_pose: [u64; 7], pub requested_names: &'static [&'static str], pub joints: &'static [NativeJointConfiguration] }
#[derive(Clone, Copy, Debug)]
pub struct NativeJointInput { pub entity: u64, pub parent_entity: u64, pub local_pose: [u64; 7], pub local_pose_getback: [u64; 7], pub position: &'static [u64], pub position_getback: &'static [u64], pub velocity: &'static [u64], pub velocity_getback: &'static [u64], pub force: &'static [u64], pub force_getback: &'static [u64] }
#[derive(Clone, Copy, Debug)]
pub struct NativeInput { pub owner: usize, pub call_index: usize, pub sim_ns: i64, pub dt_ns: i64, pub real_ns: i64, pub iterations: u64, pub paused: bool, pub model_pose: [u64; 7], pub model_pose_getback: [u64; 7], pub joints: &'static [NativeJointInput] }
#[derive(Clone, Copy, Debug)]
pub struct NativeObservation { pub owner: usize, pub call_index: usize, pub arrival_ordinal: u64, pub message: NativeModelMessage }
#[derive(Clone, Copy, Debug)]
pub struct NativeFence { pub owner: usize, pub call_index: usize, pub initial_lazy_publication: bool, pub topic_info_ok: bool, pub publishers_before: u32, pub subscribers_before: u32, pub arrivals_before: u64, pub arrivals_after: u64, pub expected_outputs: u32 }
